ALTER TABLE "products" DROP CONSTRAINT IF EXISTS "products_mvp_product_type_check";
ALTER TABLE "products" ADD CONSTRAINT "products_mvp_product_type_check" CHECK ("product_type" IN ('digital_download','course','community','membership','appointment','event_ticket'));
CREATE TABLE "booking_calendars" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"owner_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE cascade,"name" text NOT NULL,"timezone" text NOT NULL,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "booking_calendars_business_name_unique" UNIQUE("business_id","name"));
CREATE TABLE "booking_availability_rules" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"calendar_id" uuid NOT NULL REFERENCES "booking_calendars"("id") ON DELETE cascade,"day_of_week" integer NOT NULL,"start_minute" integer NOT NULL,"end_minute" integer NOT NULL,"created_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "booking_availability_valid_check" CHECK("day_of_week" BETWEEN 0 AND 6 AND "start_minute" >= 0 AND "end_minute" <= 1440 AND "end_minute" > "start_minute"));
CREATE TABLE "booking_blackouts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"calendar_id" uuid NOT NULL REFERENCES "booking_calendars"("id") ON DELETE cascade,"starts_at" timestamp NOT NULL,"ends_at" timestamp NOT NULL,"reason" text NOT NULL DEFAULT '',"created_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "booking_blackouts_valid_check" CHECK("ends_at">"starts_at"));
CREATE TABLE "appointment_types" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"owner_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"calendar_id" uuid NOT NULL REFERENCES "booking_calendars"("id") ON DELETE restrict,"name" text NOT NULL,"slug" text NOT NULL UNIQUE,"description" text NOT NULL DEFAULT '',"duration_minutes" integer NOT NULL,"buffer_before_minutes" integer NOT NULL DEFAULT 0,"buffer_after_minutes" integer NOT NULL DEFAULT 0,"capacity" integer NOT NULL DEFAULT 1,"location_mode" text NOT NULL,"location" text,"price_cents" integer NOT NULL DEFAULT 0,"currency" text NOT NULL DEFAULT 'usd',"product_id" integer REFERENCES "products"("id") ON DELETE set null,"minimum_notice_minutes" integer NOT NULL DEFAULT 60,"booking_horizon_days" integer NOT NULL DEFAULT 90,"cancellation_notice_minutes" integer NOT NULL DEFAULT 1440,"reminder_minutes" json NOT NULL DEFAULT '[1440,60]'::json,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "booking_reservations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"appointment_type_id" uuid NOT NULL REFERENCES "appointment_types"("id") ON DELETE restrict,"booker_user_id" integer REFERENCES "users"("id") ON DELETE set null,"guest_name" text NOT NULL,"guest_email" text NOT NULL,"guest_timezone" text NOT NULL,"starts_at" timestamp NOT NULL,"ends_at" timestamp NOT NULL,"status" text NOT NULL DEFAULT 'confirmed',"payment_status" text NOT NULL DEFAULT 'not_required',"order_id" uuid REFERENCES "orders"("id") ON DELETE set null,"room_id" uuid REFERENCES "community_rooms"("id") ON DELETE set null,"cancellation_reason" text,"cancelled_at" timestamp,"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "booking_reservations_status_check" CHECK("status" IN ('payment_required','confirmed','completed','cancelled','no_show','refund_required','refunded')));
CREATE INDEX "booking_reservations_type_start_idx" ON "booking_reservations"("appointment_type_id","starts_at","status");
CREATE TABLE "booking_waitlist" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"appointment_type_id" uuid NOT NULL REFERENCES "appointment_types"("id") ON DELETE cascade,"booker_user_id" integer REFERENCES "users"("id") ON DELETE set null,"guest_name" text NOT NULL,"guest_email" text NOT NULL,"guest_timezone" text NOT NULL,"starts_at" timestamp NOT NULL,"status" text NOT NULL DEFAULT 'waiting',"position" integer NOT NULL,"promoted_reservation_id" uuid REFERENCES "booking_reservations"("id") ON DELETE set null,"created_at" timestamp NOT NULL DEFAULT now(),"promoted_at" timestamp,CONSTRAINT "booking_waitlist_status_check" CHECK("status" IN ('waiting','promoted','expired','cancelled')));
CREATE TABLE "event_series" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE cascade,"timezone" text NOT NULL,"frequency" text NOT NULL,"interval_count" integer NOT NULL DEFAULT 1,"occurrence_count" integer NOT NULL,"created_by_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "event_occurrences" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"series_id" uuid NOT NULL REFERENCES "event_series"("id") ON DELETE cascade,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE cascade,"sequence" integer NOT NULL,"starts_at" timestamp NOT NULL,"status" text NOT NULL DEFAULT 'scheduled',"created_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "event_occurrences_series_sequence_unique" UNIQUE("series_id","sequence"));
CREATE TABLE "event_commercial_settings" ("event_id" uuid PRIMARY KEY REFERENCES "events"("id") ON DELETE cascade,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"timezone" text NOT NULL,"capacity" integer NOT NULL,"waitlist_enabled" boolean NOT NULL DEFAULT true,"cancellation_notice_minutes" integer NOT NULL DEFAULT 1440,"refund_policy" text NOT NULL DEFAULT 'refund_before_deadline',"room_id" uuid REFERENCES "community_rooms"("id") ON DELETE set null,"replay_asset_id" uuid REFERENCES "assets"("id") ON DELETE set null,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "event_ticket_types" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE cascade,"name" text NOT NULL,"description" text NOT NULL DEFAULT '',"price_cents" integer NOT NULL,"currency" text NOT NULL DEFAULT 'usd',"capacity" integer NOT NULL,"sales_start_at" timestamp,"sales_end_at" timestamp,"max_per_buyer" integer NOT NULL DEFAULT 10,"replay_access_days" integer NOT NULL DEFAULT 30,"product_id" integer REFERENCES "products"("id") ON DELETE set null,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "event_tickets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE restrict,"ticket_type_id" uuid NOT NULL REFERENCES "event_ticket_types"("id") ON DELETE restrict,"holder_user_id" integer REFERENCES "users"("id") ON DELETE set null,"holder_name" text NOT NULL,"holder_email" text NOT NULL,"quantity" integer NOT NULL DEFAULT 1,"status" text NOT NULL DEFAULT 'confirmed',"payment_status" text NOT NULL DEFAULT 'not_required',"order_id" uuid REFERENCES "orders"("id") ON DELETE set null,"ticket_code" text NOT NULL UNIQUE,"checked_in_at" timestamp,"cancelled_at" timestamp,"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "event_tickets_status_check" CHECK("status" IN ('payment_required','confirmed','checked_in','cancelled','refund_required','refunded')));
CREATE INDEX "event_tickets_event_status_idx" ON "event_tickets"("event_id","status");
CREATE TABLE "event_waitlist" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE cascade,"ticket_type_id" uuid NOT NULL REFERENCES "event_ticket_types"("id") ON DELETE cascade,"user_id" integer REFERENCES "users"("id") ON DELETE set null,"name" text NOT NULL,"email" text NOT NULL,"quantity" integer NOT NULL DEFAULT 1,"position" integer NOT NULL,"status" text NOT NULL DEFAULT 'waiting',"promoted_ticket_id" uuid REFERENCES "event_tickets"("id") ON DELETE set null,"created_at" timestamp NOT NULL DEFAULT now(),"promoted_at" timestamp);
CREATE TABLE "event_attendance" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE cascade,"ticket_id" uuid REFERENCES "event_tickets"("id") ON DELETE set null,"user_id" integer REFERENCES "users"("id") ON DELETE set null,"joined_at" timestamp NOT NULL DEFAULT now(),"left_at" timestamp,"source" text NOT NULL DEFAULT 'manual',"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "event_replay_entitlements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE cascade,"asset_id" uuid NOT NULL REFERENCES "assets"("id") ON DELETE restrict,"user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE cascade,"ticket_id" uuid REFERENCES "event_tickets"("id") ON DELETE set null,"expires_at" timestamp,"created_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "event_replay_user_unique" UNIQUE("event_id","asset_id","user_id"));
CREATE TABLE "event_automation_jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"event_id" uuid REFERENCES "events"("id") ON DELETE cascade,"reservation_id" uuid REFERENCES "booking_reservations"("id") ON DELETE cascade,"ticket_id" uuid REFERENCES "event_tickets"("id") ON DELETE cascade,"job_type" text NOT NULL,"recipient_user_id" integer REFERENCES "users"("id") ON DELETE set null,"recipient_email" text NOT NULL,"due_at" timestamp NOT NULL,"status" text NOT NULL DEFAULT 'queued',"payload" json NOT NULL DEFAULT '{}'::json,"attempt_count" integer NOT NULL DEFAULT 0,"created_at" timestamp NOT NULL DEFAULT now(),"sent_at" timestamp,CONSTRAINT "event_automation_target_check" CHECK("event_id" IS NOT NULL OR "reservation_id" IS NOT NULL));
CREATE INDEX "event_automation_due_idx" ON "event_automation_jobs"("status","due_at");
